arguments.new_str:
remove_yaml_frontmatter <- function(lines) {
  if (length(lines) > 0 && lines[1] == "---") {
    yaml_end <- which(lines == "---")
    if (length(yaml_end) >= 2) {
      return(lines[(yaml_end[2] + 1):length(lines)])
    }
  }
  return(lines)
}

