  if (length(lines) > 0 && lines[1] == "---") {
    yaml_end <- which(lines == "---")
    if (length(yaml_end) >= 2) {
      return(yaml_end[2] + 1)
    }
  }
  1
}

# Return example to verify
remove_yaml_frontmatter_start(c("---", "first", "second", "---", "content"))

