function (pkg_dir = ".") 
{
    vignette_files <- list.files(path = file.path(pkg_dir, "vignettes"), 
        pattern = "\\.[Rr]md$", full.names = TRUE, recursive = TRUE)
    purrr::walk(vignette_files, function(rmd_file) {
        knitr::convert_chunk_header(input = rmd_file, output = identity, 
            type = "yaml")
        cli::cli_alert_success(glue::glue("Updated chunk headers in {rmd_file}"))
    })
    length(vignette_files)
}
